    }
    for (thread_id, entry) in self.agent_navigation.ordered_threads() {
        chat_widget.set_collab_agent_metadata(
            thread_id,
            entry.agent_nickname.clone(),
            entry.agent_role.clone(),
        );
    }
    self.chat_widget = chat_widget;

