package agents

import (
	"context"
	"os"
	"strconv"
	"strings"
	"time"
)

type Output struct {
	Command  string
	Stdout   string
	Stderr   string
	ExitCode int
}

type Option func(*runConfig)
type runConfig struct {
	Model          string
	PermissionMode string
	PromptTimeout  time.Duration
}

func WithModel(model string) Option {
	return func(c *runConfig) { c.Model = model }
}

func WithPermissionMode(mode string) Option {
	return func(c *runConfig) { c.PermissionMode = mode }
}

func WithPromptTimeout(d time.Duration) Option {
	return func(c *runConfig) { c.PromptTimeout = d }
}

type Agent interface {
	Name() string
	// Binary returns the CLI binary name (e.g. "claude", "gemini").
	Binary() string
	EntireAgent() string
	PromptPattern() string
	// TimeoutMultiplier returns a factor applied to per-test timeouts.
	// Slower agents (e.g. Gemini) return values > 1.
	TimeoutMultiplier() float64
	RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error)
	StartSession(ctx context.Context, dir string) (Session, error)
	// Bootstrap performs one-time CI setup (auth config, warmup, etc.).
	// Called before any tests run. Implementations should be idempotent.
	Bootstrap() error
	// IsTransientError returns true if the error from RunPrompt looks like
	// a transient API failure (e.g. 500, rate limit, network error) that
	// is worth retrying.
	IsTransientError(out Output, err error) bool
}

type Session interface {
	Send(input string) error
	WaitFor(pattern string, timeout time.Duration) (string, error)
	Capture() string
	Close() error
}

// ExternalAgent is an optional interface for agents discovered via the
// external agent protocol (entire-agent-* binaries). SetupRepo uses this
// to pre-configure external_agents in settings before running `entire enable`.
type ExternalAgent interface {
	IsExternalAgent() bool
}

var registry []Agent
var gates = map[string]chan struct{}{}

func Register(a Agent) {
	registry = append(registry, a)
}

// RegisterGate sets a concurrency limit for an agent's tests.
// Tests call AcquireSlot/ReleaseSlot to respect this limit.
// The limit can be overridden via E2E_CONCURRENT_TEST_LIMIT.
func RegisterGate(name string, defaultMax int) {
	max := defaultMax
	if v, err := strconv.Atoi(os.Getenv("E2E_CONCURRENT_TEST_LIMIT")); err == nil && v > 0 {
		max = v
	}
	gates[name] = make(chan struct{}, max)
}

// AcquireSlot blocks until a test slot is available for the agent or the
// context is cancelled. Returns a non-nil error if the context expires
// before a slot opens.
func AcquireSlot(ctx context.Context, a Agent) error {
	g, ok := gates[a.Name()]
	if !ok {
		return nil
	}
	select {
	case g <- struct{}{}:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

// ReleaseSlot frees a test slot for the agent.
func ReleaseSlot(a Agent) {
	if g, ok := gates[a.Name()]; ok {
		<-g
	}
}

func All() []Agent {
	return registry
}

// filterEnv returns env with entries matching any of the given variable names
// removed. Used to strip test-only overrides (e.g. ENTIRE_TEST_TTY) from agent
// processes so they exercise real detection paths.
func filterEnv(env []string, names ...string) []string {
	out := make([]string, 0, len(env))
	for _, e := range env {
		skip := false
		for _, name := range names {
			if strings.HasPrefix(e, name+"=") {
				skip = true
				break
			}
		}
		if !skip {
			out = append(out, e)
		}
	}
	return out
}

package testutil

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/entireio/cli/e2e/agents"
	"github.com/entireio/cli/e2e/entire"
)

const droidRepoSettingsPath = ".factory/settings.json"

// RepoState holds the working state for a single test's cloned repository.
type RepoState struct {
	Agent            agents.Agent
	Dir              string
	ArtifactDir      string
	HeadBefore       string
	CheckpointBefore string
	ConsoleLog       *os.File
	session          agents.Session // interactive session, if started via StartSession
	skipArtifacts    bool           // suppresses artifact capture on scenario restart
}

// SetupRepo creates a fresh git repository in a temporary directory, seeds it
// with an initial commit, and runs `entire enable` for the given agent.
// Artifact capture is registered as a cleanup function.
//
// When E2E_KEEP_REPOS is set, the temporary directory is not cleaned up
// so it can be inspected after the test. A symlink in the artifact dir
// points to the preserved repo.
func SetupRepo(t *testing.T, agent agents.Agent) *RepoState {
	t.Helper()

	keepRepos := os.Getenv("E2E_KEEP_REPOS") != ""

	// Always use os.MkdirTemp instead of t.TempDir(). Go's t.TempDir()
	// creates nested subdirectories (TestName.../001/) whose structure
	// confuses some agents' (e.g. opencode) working-directory resolution.
	dir, err := os.MkdirTemp("", "e2e-repo-*")
	if err != nil {
		t.Fatalf("create temp dir: %v", err)
	}
	if keepRepos {
		t.Logf("E2E_KEEP_REPOS: repo will be preserved at %s", dir)
	} else {
		t.Cleanup(func() { os.RemoveAll(dir) })
	}

	// Resolve symlinks (macOS: /var -> /private/var) so paths match
	// what agent CLIs see when they resolve their own CWD.
	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
		dir = resolved
	}

	Git(t, dir, "init")
	Git(t, dir, "config", "user.name", "E2E Test")
	Git(t, dir, "config", "user.email", "e2e@test.local")
	Git(t, dir, "config", "core.pager", "cat")
	Git(t, dir, "config", "core.autocrlf", "true")
	Git(t, dir, "commit", "--allow-empty", "-m", "initial commit")

	// External agents need external_agents enabled in settings before enable,
	// so the CLI can discover the agent binary via PATH during DiscoverAndRegister.
	if ea, ok := agent.(agents.ExternalAgent); ok && ea.IsExternalAgent() {
		entireDir := filepath.Join(dir, ".entire")
		if err := os.MkdirAll(entireDir, 0o755); err != nil {
			t.Fatalf("create .entire for external agent: %v", err)
		}
		if err := os.WriteFile(filepath.Join(entireDir, "settings.json"),
			[]byte("{\"external_agents\": true}\n"), 0o644); err != nil {
			t.Fatalf("write external_agents setting: %v", err)
		}
	}

	entire.Enable(t, dir, agent.EntireAgent())
	if agent.Name() == "factoryai-droid" {
		if err := configureDroidRepoSettings(dir); err != nil {
			t.Fatalf("configure droid repo settings: %v", err)
		}
	}
	// commit_linking=always ensures the prepare-commit-msg hook adds the
	// Entire-Checkpoint trailer unconditionally. This is needed because
	// interactive agents run inside tmux (hasTTY()=true) but can't respond to
	// prompts, and content detection may fail on the first checkpoint when no
	// shadow branch exists yet. Prompt-mode agents still exercise the !hasTTY()
	// fast path since they have no TTY regardless of this setting.
	PatchSettings(t, dir, map[string]any{"log_level": "debug", "commit_linking": "always"})

	// Copilot CLI blocks on a "No copilot instructions found" notice in fresh
	// repos that lack .github/copilot-instructions.md, preventing the interactive
	// prompt from appearing.
	if agent.Name() == "copilot-cli" {
		ghDir := filepath.Join(dir, ".github")
		if err := os.MkdirAll(ghDir, 0o755); err != nil {
			t.Fatalf("create .github dir: %v", err)
		}
		if err := os.WriteFile(filepath.Join(ghDir, "copilot-instructions.md"), []byte("# E2E Test\n"), 0o644); err != nil {
			t.Fatalf("write copilot-instructions.md: %v", err)
		}
	}

	// OpenCode's non-interactive mode auto-rejects external_directory permission
	// since there's no user to prompt. Write a config to allow it.
	if agent.Name() == "opencode" {
		cfg := `{"$schema": "https://opencode.ai/config.json", "permission": {"external_directory": "allow"}}`
		if key := os.Getenv("ANTHROPIC_API_KEY"); key != "" {
